public class DateTimeZone_forOffsetHoursMinutes_TriageGen2Test {

    @Test
    public void testForOffsetHoursMinutes_UTC() {
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(0, 0);
        assertEquals(DateTimeZone.UTC, zone);
    }

    @Test
    public void testForOffsetHoursMinutes_PositiveOffset() {
        // Test +5:30
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(5, 30);
        int expectedOffsetMillis = (5 * 60 + 30) * DateTimeConstants.MILLIS_PER_MINUTE;
        assertEquals(expectedOffsetMillis, zone.getOffset(0));
    }

    @Test
    public void testForOffsetHoursMinutes_NegativeOffset() {
        // Test -5:30
        // The logic: hoursInMinutes = -300. minutesOffset becomes -300 - 30 = -330.
        // -330 * 60000 = -19800000
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(-5, 30);
        int expectedOffsetMillis = (-5 * 60 - 30) * DateTimeConstants.MILLIS_PER_MINUTE;
        assertEquals(expectedOffsetMillis, zone.getOffset(0));
    }

    @Test
    public void testForOffsetHoursMinutes_HoursUpperLimit() {
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(23, 0);
        int expectedOffsetMillis = 23 * 60 * DateTimeConstants.MILLIS_PER_MINUTE;
        assertEquals(expectedOffsetMillis, zone.getOffset(0));
    }

    @Test
    public void testForOffsetHoursMinutes_HoursLowerLimit() {
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(-23, 0);
        int expectedOffsetMillis = -23 * 60 * DateTimeConstants.MILLIS_PER_MINUTE;
        assertEquals(expectedOffsetMillis, zone.getOffset(0));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_HoursTooHigh() {
        DateTimeZone.forOffsetHoursMinutes(24, 0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_HoursTooLow() {
        DateTimeZone.forOffsetHoursMinutes(-24, 0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_MinutesInvalidHigh() {
        // minutesOffset must be 0 based on the check: if (minutesOffset < 0 || minutesOffset > 0)
        // Note: The provided source code logic implies minutesOffset can ONLY be 0.
        // If the intent was to allow 0-59, the code provided is strictly checking for 0.
        DateTimeZone.forOffsetHoursMinutes(5, 1);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_MinutesInvalidLow() {
        DateTimeZone.forOffsetHoursMinutes(5, -1);
    }

    @Test
    public void testForOffsetHoursMinutes_ArithmeticExceptionTrigger() {
        // To trigger ArithmeticException in FieldUtils.safeMultiply or overflow in int calculation.
        // Since hours is capped at 23, we can't easily overflow 'hoursInMinutes'.
        // However, we can attempt to trigger the catch block if the logic allowed larger inputs.
        // Given the constraints (hours -23 to 23), the offset calculation is safe from overflow.
        // But we must ensure the code path is considered.
        // If we cannot trigger it with valid inputs, we acknowledge the constraint.
    }
